from std.memory.alloc import alloc, dealloc

def sum_squares() -> Int:
    var allocation = alloc[Int]({count = 3})
    var ptr = allocation.unsafe_ptr()
    for i in range(3):
        ptr.unsafe_offset(i).unsafe_write(i * i)
    var total = ptr[unsafe_offset=0] + ptr[unsafe_offset=1] + ptr[unsafe_offset=2]
    dealloc(allocation^)
    return total

def main():
    print(sum_squares())

def largest[T: Copyable & Comparable](values: List[T]) -> T:
    var best_index = 0
    for i in range(1, len(values)):
        if values[i] > values[best_index]:
            best_index = i
    return values[best_index].copy()

